//go:build auth

package auth

import (
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
	"gorm.io/gorm"
)

var _ = Describe("emailForRoleDecision", func() {
	It("returns the email when verified", func() {
		Expect(emailForRoleDecision("admin@example.com", true)).
			To(Equal("admin@example.com"))
	})

	It("returns empty when not verified", func() {
		Expect(emailForRoleDecision("admin@example.com", false)).
			To(Equal(""))
	})

	It("returns empty when email is empty regardless of flag", func() {
		Expect(emailForRoleDecision("", true)).To(Equal(""))
		Expect(emailForRoleDecision("", false)).To(Equal(""))
	})

	Context("integration with AssignRole", func() {
		var db *gorm.DB

		BeforeEach(func() {
			db, _ = InitDB(":memory:")
			// Seed at least one user so the "first user becomes admin"
			// branch doesn't hide the gate we're testing.
			seed := &User{
				ID:       "seed-user",
				Email:    "seed@example.com",
				Provider: ProviderGitHub,
				Subject:  "seed",
				Role:     RoleAdmin,
				Status:   StatusActive,
			}
			Expect(db.Create(seed).Error).To(Succeed())
		})

		It("does NOT promote on unverified email matching admin email", func() {
			role := AssignRole(db, emailForRoleDecision("admin@example.com", false), "admin@example.com")
			Expect(role).To(Equal(RoleUser),
				"unverified IdP claim of admin email must not yield admin role")
		})

		It("DOES promote on verified email matching admin email", func() {
			role := AssignRole(db, emailForRoleDecision("admin@example.com", true), "admin@example.com")
			Expect(role).To(Equal(RoleAdmin))
		})

		It("ignores email when admin email is unset, regardless of verification", func() {
			role := AssignRole(db, emailForRoleDecision("any@example.com", true), "")
			Expect(role).To(Equal(RoleUser))
		})
	})
})

// SPDX-License-Identifier: MIT
package agentpool_test

import (
	"context"
	"log/slog"
	"os"
	"path/filepath"
	"strings"

	"github.com/mudler/LocalAI/core/config"
	"github.com/mudler/LocalAI/core/services/agentpool"
	"github.com/mudler/xlog"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("legacy auth warning", func() {
	const warning = "User authentication is enabled but root agent data has no owner"
	var dir string
	var logFile *os.File

	BeforeEach(func() {
		dir = GinkgoT().TempDir()
		var err error
		logFile, err = os.CreateTemp(dir, "startup-*.log")
		Expect(err).NotTo(HaveOccurred())
		xlog.SetLogger(xlog.NewLoggerWithHandler(slog.NewTextHandler(logFile, nil), xlog.LogLevelInfo))
	})
	AfterEach(func() {
		xlog.SetLogger(xlog.NewLogger(xlog.LogLevelInfo, "text"))
		Expect(logFile.Close()).To(Succeed())
	})

	write := func(path, data string) {
		Expect(os.MkdirAll(filepath.Dir(path), 0750)).To(Succeed())
		Expect(os.WriteFile(path, []byte(data), 0600)).To(Succeed())
	}
	start := func(enabled bool, collectionPath string) string {
		cfg := config.NewApplicationConfig()
		cfg.Auth.Enabled = enabled
		cfg.AgentPool = config.AgentPoolConfig{
			Enabled: true, StateDir: dir, APIURL: "http://127.0.0.1:1",
			DefaultModel: "unused", CollectionDBPath: collectionPath,
		}
		svc, err := agentpool.NewAgentPoolService(cfg)
		Expect(err).NotTo(HaveOccurred())
		Expect(svc.Start(context.Background())).To(Succeed())
		svc.Stop()
		data, err := os.ReadFile(logFile.Name())
		Expect(err).NotTo(HaveOccurred())
		return string(data)
	}

	It("warns about root agents, custom-path collections, skills and git repositories", func() {
		write(filepath.Join(dir, "pool.json"), `{"legacy":{"name":"legacy","model":"unused"},"owner:private":{"name":"owner:private","model":"unused"}}`)
		collectionsDir := filepath.Join(GinkgoT().TempDir(), "collections")
		write(filepath.Join(collectionsDir, "collection-notes.json"), `{}`)
		write(filepath.Join(dir, "skills", "legacy-skill", "SKILL.md"), "---\nname: legacy-skill\ndescription: A legacy skill\n---\nInstructions\n")
		write(filepath.Join(dir, "skills", ".git-repos.json"), `[{"id":"old","name":"old","url":"https://example.invalid/old.git","enabled":false}]`)
		logs := start(true, collectionsDir)
		Expect(logs).To(ContainSubstring(warning))
		Expect(logs).To(ContainSubstring("agents=1 collections=1 skills=1 git_repositories=1"))
		Expect(logs).To(ContainSubstring("authentication/#enabling-auth-on-an-existing-instance"))
		Expect(logs).NotTo(ContainSubstring("agents=2"))
		Expect(strings.Index(logs, warning)).To(BeNumerically("<", strings.Index(logs, "Creating agent")))
	})

	It("does not warn when auth is disabled", func() {
		write(filepath.Join(dir, "skills", "legacy-skill", "SKILL.md"), "---\nname: legacy-skill\ndescription: A legacy skill\n---\nInstructions\n")
		Expect(start(false, "")).NotTo(ContainSubstring(warning))
	})

	It("does not count user-owned data as root data", func() {
		write(filepath.Join(dir, "pool.json"), `{"owner:private":{"name":"owner:private","model":"unused"}}`)
		write(filepath.Join(dir, "users", "owner", "collections", "collection-notes.json"), `{}`)
		write(filepath.Join(dir, "users", "owner", "skills", "private", "SKILL.md"), "---\nname: private\ndescription: Private skill\n---\nInstructions\n")
		Expect(start(true, "")).NotTo(ContainSubstring(warning))
	})

	It("warns for configured git repositories even without installed skills", func() {
		write(filepath.Join(dir, "skills", ".git-repos.json"), `[{"id":"old","name":"old","url":"https://example.invalid/old.git","enabled":false}]`)
		logs := start(true, "")
		Expect(logs).To(ContainSubstring(warning))
		Expect(logs).To(ContainSubstring("agents=0 collections=0 skills=0 git_repositories=1"))
	})

	It("reports an unreadable repository config without preventing startup", func() {
		write(filepath.Join(dir, "collections", "collection-notes.json"), `{}`)
		write(filepath.Join(dir, "skills", ".git-repos.json"), `invalid json`)
		logs := start(true, "")
		Expect(logs).To(ContainSubstring("Could not check root skill repositories"))
		Expect(logs).To(ContainSubstring(warning))
		Expect(logs).To(ContainSubstring("agents=0 collections=1"))
	})
})

import { test, expect } from './coverage-fixtures.js'

// Regression: opening the installed model detail menu must not move the page
// or detach the fixed-position menu from its trigger.
test('the installed model action menu stays beside its trigger', async ({ page }) => {
  await page.setViewportSize({ width: 1024, height: 500 })
  await page.goto('/app/models?view=installed')
  await page.locator('[data-testid="installed-models-rail-item"]').first().click()

  const trigger = page.locator('button.action-menu__trigger').first()
  await expect(trigger).toBeVisible()
  await trigger.scrollIntoViewIfNeeded()
  const scrollBefore = await page.evaluate(() => window.scrollY)
  await trigger.click()

  const menu = page.locator('[role="menu"]')
  await expect(menu).toBeVisible()
  expect(await page.evaluate(() => window.scrollY)).toBe(scrollBefore)

  const triggerBox = await trigger.boundingBox()
  const menuBox = await menu.boundingBox()
  expect(triggerBox).not.toBeNull()
  expect(menuBox).not.toBeNull()
  const tracksTrigger =
    Math.abs(menuBox.y - (triggerBox.y + triggerBox.height)) < 24 ||
    Math.abs((menuBox.y + menuBox.height) - triggerBox.y) < 24
  expect(tracksTrigger).toBe(true)
  await expect(page.locator('body > .popover')).toHaveCount(1)
})

import { test, expect } from './coverage-fixtures.js'

test.describe('Installed model backend logs link', () => {
  test('the detail action menu exposes Backend logs with a terminal icon', async ({ page }) => {
    await page.goto('/app/models?view=installed')
    await page.locator('[data-testid="installed-models-rail-item"]').first().click()
    const trigger = page.locator('button.action-menu__trigger').first()
    await expect(trigger).toBeVisible()
    await trigger.click()

    const logsItem = page.getByRole('menuitem', { name: 'Backend logs' })
    await expect(logsItem).toBeVisible()
    await expect(logsItem.locator('svg[data-icon="terminal"]')).toBeVisible()
  })

  test('Backend logs navigates to the selected model logs', async ({ page }) => {
    await page.goto('/app/models?view=installed')
    await page.locator('[data-testid="installed-models-rail-item"]').first().click()
    await page.locator('button.action-menu__trigger').first().click()
    await page.getByRole('menuitem', { name: 'Backend logs' }).click()

    await expect(page).toHaveURL(/\/app\/backend-logs\//)
  })

  test('arrow navigation announces the active action through the focused menu', async ({ page }) => {
    await page.goto('/app/models?view=installed')
    await page.locator('[data-testid="installed-models-rail-item"]').first().click()
    const trigger = page.locator('button.action-menu__trigger').first()
    await trigger.focus()
    await trigger.press('Enter')

    const menu = page.getByRole('menu')
    await expect(menu).toBeFocused()
    const firstItem = menu.getByRole('menuitem').first()
    await expect(menu).toHaveAttribute('aria-activedescendant', await firstItem.getAttribute('id'))

    await menu.press('ArrowDown')
    const secondItem = menu.getByRole('menuitem').nth(1)
    await expect(menu).toHaveAttribute('aria-activedescendant', await secondItem.getAttribute('id'))
    await expect(menu).toBeFocused()
    await expect(firstItem).toHaveAttribute('tabindex', '-1')
    await expect(secondItem).toHaveAttribute('tabindex', '-1')
  })
})

//go:build auth

package auth_test

import (
	"strings"
	"time"

	"github.com/mudler/LocalAI/core/http/auth"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
	"gorm.io/gorm"
)

var _ = Describe("API Keys", func() {
	var (
		db   *gorm.DB
		user *auth.User
	)

	// Use empty HMAC secret for tests (falls back to plain SHA-256)
	hmacSecret := ""

	BeforeEach(func() {
		db = testDB()
		user = createTestUser(db, "apikey@example.com", auth.RoleUser, auth.ProviderGitHub)
	})

	Describe("GenerateAPIKey", func() {
		It("returns key with 'lai-' prefix", func() {
			plaintext, _, _, err := auth.GenerateAPIKey(hmacSecret)
			Expect(err).ToNot(HaveOccurred())
			Expect(plaintext).To(HavePrefix("lai-"))
		})

		It("returns consistent hash for same plaintext", func() {
			plaintext, hash, _, err := auth.GenerateAPIKey(hmacSecret)
			Expect(err).ToNot(HaveOccurred())
			Expect(auth.HashAPIKey(plaintext, hmacSecret)).To(Equal(hash))
		})

		It("returns prefix for display", func() {
			_, _, prefix, err := auth.GenerateAPIKey(hmacSecret)
			Expect(err).ToNot(HaveOccurred())
			Expect(prefix).To(HavePrefix("lai-"))
			Expect(len(prefix)).To(Equal(12)) // "lai-" + 8 chars
		})

		It("generates unique keys", func() {
			key1, _, _, _ := auth.GenerateAPIKey(hmacSecret)
			key2, _, _, _ := auth.GenerateAPIKey(hmacSecret)
			Expect(key1).ToNot(Equal(key2))
		})
	})

	Describe("CreateAPIKey", func() {
		It("stores hashed key in DB", func() {
			plaintext, record, err := auth.CreateAPIKey(db, user.ID, "test key", auth.RoleUser, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())
			Expect(plaintext).To(HavePrefix("lai-"))
			Expect(record.KeyHash).To(Equal(auth.HashAPIKey(plaintext, hmacSecret)))
		})

		It("does not store plaintext in DB", func() {
			plaintext, _, err := auth.CreateAPIKey(db, user.ID, "test key", auth.RoleUser, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())

			var keys []auth.UserAPIKey
			db.Find(&keys)
			for _, k := range keys {
				Expect(k.KeyHash).ToNot(Equal(plaintext))
				Expect(strings.Contains(k.KeyHash, "lai-")).To(BeFalse())
			}
		})

		It("inherits role from parameter", func() {
			_, record, err := auth.CreateAPIKey(db, user.ID, "admin key", auth.RoleAdmin, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())
			Expect(record.Role).To(Equal(auth.RoleAdmin))
		})
	})

	Describe("ValidateAPIKey", func() {
		It("returns UserAPIKey for valid key", func() {
			plaintext, _, err := auth.CreateAPIKey(db, user.ID, "valid key", auth.RoleUser, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())

			found, err := auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).ToNot(HaveOccurred())
			Expect(found).ToNot(BeNil())
			Expect(found.UserID).To(Equal(user.ID))
		})

		It("returns error for invalid key", func() {
			_, err := auth.ValidateAPIKey(db, "lai-invalidkey12345678901234567890", hmacSecret)
			Expect(err).To(HaveOccurred())
		})

		It("updates LastUsed timestamp", func() {
			plaintext, record, err := auth.CreateAPIKey(db, user.ID, "used key", auth.RoleUser, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())
			Expect(record.LastUsed).To(BeNil())

			_, err = auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).ToNot(HaveOccurred())

			var updated auth.UserAPIKey
			db.First(&updated, "id = ?", record.ID)
			Expect(updated.LastUsed).ToNot(BeNil())
		})

		It("loads associated user", func() {
			plaintext, _, err := auth.CreateAPIKey(db, user.ID, "with user", auth.RoleUser, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())

			found, err := auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).ToNot(HaveOccurred())
			Expect(found.User.ID).To(Equal(user.ID))
			Expect(found.User.Email).To(Equal("apikey@example.com"))
		})
	})

	Describe("ListAPIKeys", func() {
		It("returns all keys for the user", func() {
			auth.CreateAPIKey(db, user.ID, "key1", auth.RoleUser, hmacSecret, nil)
			auth.CreateAPIKey(db, user.ID, "key2", auth.RoleUser, hmacSecret, nil)

			keys, err := auth.ListAPIKeys(db, user.ID)
			Expect(err).ToNot(HaveOccurred())
			Expect(keys).To(HaveLen(2))
		})

		It("does not return other users' keys", func() {
			other := createTestUser(db, "other@example.com", auth.RoleUser, auth.ProviderGitHub)
			auth.CreateAPIKey(db, user.ID, "my key", auth.RoleUser, hmacSecret, nil)
			auth.CreateAPIKey(db, other.ID, "other key", auth.RoleUser, hmacSecret, nil)

			keys, err := auth.ListAPIKeys(db, user.ID)
			Expect(err).ToNot(HaveOccurred())
			Expect(keys).To(HaveLen(1))
			Expect(keys[0].Name).To(Equal("my key"))
		})
	})

	Context("with HMAC secret", func() {
		hmacSecretVal := "test-hmac-secret-456"

		It("generates different hash than empty secret", func() {
			plaintext, _, _, err := auth.GenerateAPIKey("")
			Expect(err).ToNot(HaveOccurred())

			hashEmpty := auth.HashAPIKey(plaintext, "")
			hashHMAC := auth.HashAPIKey(plaintext, hmacSecretVal)
			Expect(hashEmpty).ToNot(Equal(hashHMAC))
		})

		It("round-trips CreateAPIKey and ValidateAPIKey with HMAC secret", func() {
			plaintext, _, err := auth.CreateAPIKey(db, user.ID, "hmac key", auth.RoleUser, hmacSecretVal, nil)
			Expect(err).ToNot(HaveOccurred())

			found, err := auth.ValidateAPIKey(db, plaintext, hmacSecretVal)
			Expect(err).ToNot(HaveOccurred())
			Expect(found).ToNot(BeNil())
			Expect(found.UserID).To(Equal(user.ID))
		})

		It("does not validate with wrong HMAC secret", func() {
			plaintext, _, err := auth.CreateAPIKey(db, user.ID, "hmac key2", auth.RoleUser, hmacSecretVal, nil)
			Expect(err).ToNot(HaveOccurred())

			_, err = auth.ValidateAPIKey(db, plaintext, "wrong-secret")
			Expect(err).To(HaveOccurred())
		})

		It("does not validate key created with empty secret using non-empty secret", func() {
			plaintext, _, err := auth.CreateAPIKey(db, user.ID, "empty-secret key", auth.RoleUser, "", nil)
			Expect(err).ToNot(HaveOccurred())

			_, err = auth.ValidateAPIKey(db, plaintext, hmacSecretVal)
			Expect(err).To(HaveOccurred())
		})

		It("does not validate key created with non-empty secret using empty secret", func() {
			plaintext, _, err := auth.CreateAPIKey(db, user.ID, "nonempty-secret key", auth.RoleUser, hmacSecretVal, nil)
			Expect(err).ToNot(HaveOccurred())

			_, err = auth.ValidateAPIKey(db, plaintext, "")
			Expect(err).To(HaveOccurred())
		})
	})

	Describe("RevokeAPIKey", func() {
		It("deletes the key record", func() {
			plaintext, record, err := auth.CreateAPIKey(db, user.ID, "to revoke", auth.RoleUser, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())

			err = auth.RevokeAPIKey(db, record.ID, user.ID)
			Expect(err).ToNot(HaveOccurred())

			_, err = auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).To(HaveOccurred())
		})

		It("only allows owner to revoke their own key", func() {
			_, record, err := auth.CreateAPIKey(db, user.ID, "mine", auth.RoleUser, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())

			other := createTestUser(db, "attacker@example.com", auth.RoleUser, auth.ProviderGitHub)
			err = auth.RevokeAPIKey(db, record.ID, other.ID)
			Expect(err).To(HaveOccurred())
		})
	})

	Describe("SetAPIKeyPause", func() {
		var (
			plaintext string
			record    *auth.UserAPIKey
		)

		BeforeEach(func() {
			var err error
			plaintext, record, err = auth.CreateAPIKey(db, user.ID, "pausable", auth.RoleUser, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())
		})

		It("keeps new keys active", func() {
			Expect(record.Disabled).To(BeFalse())
			Expect(record.PausedUntil).To(BeNil())
		})

		It("rejects a key paused indefinitely and accepts it after resume", func() {
			Expect(auth.SetAPIKeyPause(db, record.ID, user.ID, true, nil)).To(Succeed())

			_, err := auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).To(MatchError(ContainSubstring("paused")))

			Expect(auth.SetAPIKeyPause(db, record.ID, user.ID, false, nil)).To(Succeed())
			_, err = auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).ToNot(HaveOccurred())
		})

		It("rejects a key paused until a future time", func() {
			until := time.Now().Add(time.Hour)
			Expect(auth.SetAPIKeyPause(db, record.ID, user.ID, false, &until)).To(Succeed())

			_, err := auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).To(MatchError(ContainSubstring("paused")))
		})

		It("does not update last_used for a paused key", func() {
			Expect(auth.SetAPIKeyPause(db, record.ID, user.ID, true, nil)).To(Succeed())
			_, _ = auth.ValidateAPIKey(db, plaintext, hmacSecret)

			keys, err := auth.ListAPIKeys(db, user.ID)
			Expect(err).ToNot(HaveOccurred())
			Expect(keys[0].LastUsed).To(BeNil())
		})

		It("treats a pause time that has passed as active again", func() {
			past := time.Now().Add(-time.Minute)
			Expect(db.Model(&auth.UserAPIKey{}).Where("id = ?", record.ID).
				Update("paused_until", past).Error).To(Succeed())

			_, err := auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).ToNot(HaveOccurred())
		})

		It("rejects a pause time in the past", func() {
			past := time.Now().Add(-time.Minute)
			err := auth.SetAPIKeyPause(db, record.ID, user.ID, false, &past)
			Expect(err).To(MatchError(auth.ErrPauseInPast))
		})

		It("only allows the owner to pause a key", func() {
			other := createTestUser(db, "other-pauser@example.com", auth.RoleAdmin, auth.ProviderGitHub)
			err := auth.SetAPIKeyPause(db, record.ID, other.ID, true, nil)
			Expect(err).To(HaveOccurred())

			_, err = auth.ValidateAPIKey(db, plaintext, hmacSecret)
			Expect(err).ToNot(HaveOccurred())
		})
	})
})

import { test, expect } from './coverage-fixtures.js'
import { mockLedger } from './ledger-fixtures.js'

// The Explore inspector holds the model's actions in its header. Whatever the
// pane width, none of them may spill past the pane, and the text must sit
// inside the pane's padding rather than against its border.

const pane = (page) => page.getByTestId('discover-pane')
const SHOTS = process.env.EXPLORE_PANE_SHOTS

async function openModel(page, name) {
  await mockLedger(page)
  await page.goto('/app/models')
  // Search first: on a phone the grouped list is long and the row may sit
  // below a collapsed group.
  await expect(page.getByTestId('models-search')).toBeVisible({ timeout: 15_000 })
  await page.getByTestId('models-search').fill(name)
  const row = page.locator(`[data-entity="${name}"]`)
  await expect(row).toBeVisible({ timeout: 15_000 })
  await row.click()
  await expect(pane(page).locator('.detail-pane')).toBeVisible()
}

async function expectButtonsInside(page) {
  const box = await pane(page).boundingBox()
  const buttons = pane(page).locator('.detail-pane__actions button:visible')
  const count = await buttons.count()
  expect(count).toBeGreaterThan(0)
  for (let i = 0; i < count; i++) {
    const b = await buttons.nth(i).boundingBox()
    expect(b.x, `button ${i} left edge`).toBeGreaterThanOrEqual(box.x)
    expect(b.x + b.width, `button ${i} right edge`).toBeLessThanOrEqual(box.x + box.width)
  }
  const scrolls = await pane(page).evaluate((el) => el.scrollWidth > el.clientWidth + 1)
  expect(scrolls).toBe(false)
}

for (const theme of ['light', 'dark']) {
  for (const [label, width] of [['wide', 1440], ['pane-1100', 1100], ['pane-920', 920]]) {
    for (const [kind, name] of [['installed', 'qwen3-8b-instruct'], ['available', 'qwen3-32b-instruct']]) {
      test(`${kind} model actions stay inside the pane (${theme}, ${label})`, async ({ page }) => {
        await page.addInitScript((m) => localStorage.setItem('localai-theme', m), theme)
        await page.setViewportSize({ width, height: 900 })
        await openModel(page, name)
        await expectButtonsInside(page)
        // Padding: the pane's first text sits clear of its border.
        const padding = await pane(page).evaluate((el) => parseFloat(getComputedStyle(el).paddingLeft))
        expect(padding).toBeGreaterThanOrEqual(16)
        const head = await pane(page).locator('.detail-pane__name').boundingBox()
        const box = await pane(page).boundingBox()
        expect(head.x - box.x).toBeGreaterThanOrEqual(16)
        if (SHOTS) await pane(page).screenshot({ path: `${SHOTS}/${kind}-${theme}-${label}.png` })
      })
    }
  }
}

test('a 320px pane keeps the actions inside it', async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 900 })
  await openModel(page, 'qwen3-8b-instruct')
  await pane(page).evaluate((el) => { el.style.width = '320px'; el.style.maxWidth = '320px'; el.style.justifySelf = 'start' })
  await expectButtonsInside(page)
